Devops wants security test cases for this stack before we go to prod. It's a photo-sharing app, and I don't have a threat model for it, just the Terraform and what I know.

```hcl
resource "aws_s3_bucket" "photos" {
  bucket = "snapshare-photos-prod"
  acl    = "public-read"
}

resource "aws_security_group" "db" {
  name = "snapshare-db"
  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_policy" "api_role" {
  name   = "snapshare-api"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = "s3:*"
      Resource = "*"
    }]
  })
}
```

